mapper.select:
SELECT DISTINCT a.APPLY_NO FROM tb_accept_apply_detail d INNER JOIN tb_accept_apply a ON d.ACCEPT_APPLY_NO = a.APPLY_NO INNER JOIN tb_purchase_contract pc ON a.PURCHASE_CONTRACT_NO = pc.APPLY_NO LEFT JOIN `ACT_HI_PROCINST` hp ON a.PROCESS_INSTANCE_ID = hp.`PROC_INST_ID_` WHERE a.STATUS = 1 AND a.ACCEPT_CATEGORY = 1 AND d.IS_DELETED = 0 AND a.IS_DELETED = 0 AND pc.IS_DELETED = 0 AND a.CREATE_TIME >= '2026-05-28 00:00:00' AND (a.SEND_SUPPLIER = 1 OR #{isAdmin} = true) AND NOT EXISTS ( SELECT 1 FROM tb_purchase_contract_pay pcp WHERE pcp.ACCEPT_APPLY_NO = a.APPLY_NO AND IFNULL(pcp.IS_DELETED, 0) = 0 )
AND pc.SUPPLIER_NO = #{supplierNo}
AND a.APPLY_NO LIKE CONCAT('%', #{acceptApplyNo}, '%')
AND d.PARTS_NO LIKE CONCAT('%', #{partsNo}, '%')
AND d.PARTS_NAME LIKE CONCAT('%', #{partsName}, '%')
ORDER BY hp.END_TIME_ DESC LIMIT #{limit} OFFSET #{offset}

SELECT DISTINCT d.ID AS accept_detail_id, a.APPLY_NO AS accept_apply_no, a.DOC_TITLE AS doc_title, d.PARTS_NO AS parts_no, d.PARTS_NAME AS parts_name, d.REMARK AS remark, d.UNIT_NAME AS unit_name, d.QUANTITY AS quantity, d.TOTAL_PRICE_RMB AS amount, a.ACCEPT_CATEGORY AS accept_category, a.STATUS AS accept_status, bc.SUPPLIER_NO AS supplier_no, bc.SUPPLIER_NAME AS supplier_name, a.BOM_PURCHASE_ORDER_NO AS contract_no, a.BOM_PURCHASE_CONTRACT_NAME AS contract_name, COALESCE(hp.END_TIME_, a.CREATE_TIME) AS accept_date, a.PROCESS_INSTANCE_ID AS process_instance_id, pd.PROJECT_NAME AS project_name, po.PURCHASE_ORDER_TYPE AS purchase_order_type FROM tb_accept_apply_detail d INNER JOIN tb_accept_apply a ON d.ACCEPT_APPLY_NO = a.APPLY_NO INNER JOIN tb_bom_purchase_contract bc ON a.BOM_PURCHASE_CONTRACT_NO = bc.APPLY_NO INNER JOIN tb_bom_purchase_order po ON a.BOM_PURCHASE_ORDER_NO = po.APPLY_NO AND po.IS_DELETED = 0 LEFT JOIN tb_bom_purchase_order_detail pd ON pd.BOM_PURCHASE_ORDER_NO = a.BOM_PURCHASE_ORDER_NO AND pd.IS_DELETED = 0 LEFT JOIN `ACT_HI_PROCINST` hp ON a.PROCESS_INSTANCE_ID = hp.`PROC_INST_ID_` LEFT JOIN tb_bom_purchase_contract_pay bcp ON bcp.ACCEPT_APPLY_NO = a.APPLY_NO AND IFNULL(bcp.IS_DELETED, 0) = 0 WHERE a.STATUS = 1 AND a.ACCEPT_CATEGORY = 2 AND d.IS_DELETED = 0 AND a.IS_DELETED = 0 AND bc.IS_DELETED = 0 AND bcp.ACCEPT_APPLY_NO IS NULL AND a.CREATE_TIME >= '2026-05-27 00:00:00' AND (a.SEND_SUPPLIER = 1 OR #{isAdmin} = true)
AND bc.SUPPLIER_NO = #{supplierNo}
AND a.APPLY_NO IN
#{no}
ORDER BY hp.END_TIME_ DESC

SELECT DISTINCT d.ID AS accept_detail_id, a.APPLY_NO AS accept_apply_no, a.DOC_TITLE AS doc_title, d.PARTS_NO AS parts_no, d.PARTS_NAME AS parts_name, d.REMARK AS remark, d.UNIT_NAME AS unit_name, d.QUANTITY AS quantity, d.TOTAL_PRICE_RMB AS amount, a.ACCEPT_CATEGORY AS accept_category, a.STATUS AS accept_status, pc.SUPPLIER_NO AS supplier_no, cs.SUPPLIER_NAME AS supplier_name, a.PURCHASE_CONTRACT_NO AS contract_no, a.PURCHASE_CONTRACT_NAME AS contract_name, COALESCE(hp.END_TIME_, a.CREATE_TIME) AS accept_date, a.PROCESS_INSTANCE_ID AS process_instance_id, pcd.PROJECT_NAME AS project_name, pc.PURCHASE_ORDER_TYPE AS purchase_order_type FROM tb_accept_apply_detail d INNER JOIN tb_accept_apply a ON d.ACCEPT_APPLY_NO = a.APPLY_NO INNER JOIN tb_purchase_contract pc ON a.PURCHASE_CONTRACT_NO = pc.APPLY_NO LEFT JOIN tb_contract_supplier cs ON pc.SUPPLIER_NO = cs.SUPPLIER_NO AND cs.IS_DELETED = 0 LEFT JOIN `ACT_HI_PROCINST` hp ON a.PROCESS_INSTANCE_ID = hp.`PROC_INST_ID_` LEFT JOIN tb_purchase_contract_detail pcd ON a.PURCHASE_APPLY_NO = pcd.PURCHASE_NO AND pcd.IS_DELETED = 0 LEFT JOIN tb_purchase_contract_pay pcp ON pcp.ACCEPT_APPLY_NO = a.APPLY_NO AND IFNULL(pcp.IS_DELETED, 0) = 0 WHERE a.STATUS = 1 AND a.ACCEPT_CATEGORY = 1 AND d.IS_DELETED = 0 AND a.IS_DELETED = 0 AND pc.IS_DELETED = 0 AND pcp.ACCEPT_APPLY_NO IS NULL AND a.CREATE_TIME >= '2026-05-27 00:00:00' AND (a.SEND_SUPPLIER = 1 OR #{isAdmin} = true)
AND pc.SUPPLIER_NO = #{supplierNo}
AND a.APPLY_NO IN
#{no}
ORDER BY hp.END_TIME_ DESC

SELECT DISTINCT pc.APPLY_NO FROM tb_purchase_order a INNER JOIN tb_purchase_contract pc ON a.CONTRACT_NO = pc.APPLY_NO AND pc.IS_DELETED = 0 WHERE a.STATUS = 0 AND IFNULL(a.IS_DELETED, 0) = 0
AND pc.SUPPLIER_NO = #{supplierNo}
ORDER BY a.CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

SELECT DISTINCT a.PURCHASE_CONTRACT_NO FROM tb_accept_apply_detail d INNER JOIN tb_accept_apply a ON d.ACCEPT_APPLY_NO = a.APPLY_NO INNER JOIN tb_purchase_contract pc ON a.PURCHASE_CONTRACT_NO = pc.APPLY_NO WHERE a.STATUS = 1 AND a.ACCEPT_CATEGORY = 1 AND d.IS_DELETED = 0 AND a.IS_DELETED = 0 AND pc.IS_DELETED = 0 AND a.CREATE_TIME >= '2026-05-28 00:00:00' AND (a.SEND_SUPPLIER = 1 OR #{isAdmin} = true) AND NOT EXISTS ( SELECT 1 FROM tb_purchase_contract_pay pcp WHERE pcp.ACCEPT_APPLY_NO = a.APPLY_NO AND IFNULL(pcp.IS_DELETED, 0) = 0 )
AND pc.SUPPLIER_NO = #{supplierNo}
ORDER BY a.CREATE_TIME DESC LIMIT #{limit}

SELECT DISTINCT a.BOM_PURCHASE_ORDER_NO FROM tb_accept_apply_detail d INNER JOIN tb_accept_apply a ON d.ACCEPT_APPLY_NO = a.APPLY_NO INNER JOIN tb_bom_purchase_contract bc ON a.BOM_PURCHASE_CONTRACT_NO = bc.APPLY_NO INNER JOIN tb_bom_purchase_order po ON a.BOM_PURCHASE_ORDER_NO = po.APPLY_NO AND po.IS_DELETED = 0 WHERE a.STATUS = 1 AND a.ACCEPT_CATEGORY = 2 AND d.IS_DELETED = 0 AND a.IS_DELETED = 0 AND bc.IS_DELETED = 0 AND a.CREATE_TIME >= '2026-05-27 00:00:00' AND (a.SEND_SUPPLIER = 1 OR #{isAdmin} = true) AND NOT EXISTS ( SELECT 1 FROM tb_bom_purchase_contract_pay bcp WHERE bcp.ACCEPT_APPLY_NO = a.APPLY_NO AND IFNULL(bcp.IS_DELETED, 0) = 0 )
AND bc.SUPPLIER_NO = #{supplierNo}
ORDER BY a.CREATE_TIME DESC LIMIT #{limit}

mapper.insert:
INSERT INTO tb_settlement_order (
    SETTLEMENT_NO, supplier_no, supplier_name,
    INVOICE_AMOUNT, INVOICE_TAX_RATE, INVOICE_TAX_AMOUNT, INVOICE_TOTAL_AMOUNT,
    remark, STATUS, CREATE_USER, CREATE_DEPT, ACCEPT_DETAIL_IDS, ACCEPT_APPLY_NO
) VALUES (
    #{settlementNo}, #{supplierNo}, #{supplierName},
    #{invoiceAmount}, #{invoiceTaxRate}, #{invoiceTaxAmount}, #{invoiceTotalAmount},
    #{remark}, 0, #{createUser}, #{createDept}, #{acceptDetailIds}, #{acceptApplyNo}
)

mapper.select:
SELECT s.ID AS id, s.SETTLEMENT_NO AS settlement_no, s.supplier_no AS supplier_no, c.SUPPLIER_NAME AS supplier_name, s.INVOICE_TOTAL_AMOUNT AS invoice_total_amount, CASE WHEN EXISTS ( SELECT 1 FROM tb_purchase_contract_pay pcp WHERE pcp.ACCEPT_APPLY_NO = s.ACCEPT_APPLY_NO AND pcp.STATUS = 1 AND IFNULL(pcp.IS_DELETED, 0) = 0 UNION ALL SELECT 1 FROM tb_bom_purchase_contract_pay bcp WHERE bcp.ACCEPT_APPLY_NO = s.ACCEPT_APPLY_NO AND bcp.STATUS = 1 AND IFNULL(bcp.IS_DELETED, 0) = 0 ) THEN 2 ELSE s.STATUS END AS status, s.CREATE_TIME AS create_time, s.ACCEPT_APPLY_NO AS accept_apply_no, a.BOM_PURCHASE_ORDER_NO AS bom_purchase_order_no, CASE WHEN a.ACCEPT_CATEGORY = 1 THEN a.PURCHASE_CONTRACT_NO ELSE a.BOM_PURCHASE_CONTRACT_NO END AS contract_no, GROUP_CONCAT(DISTINCT l.INVOICE_NO ORDER BY l.ID SEPARATOR ',') AS invoice_no, GROUP_CONCAT(DISTINCT l.INVOICE_DATE ORDER BY l.ID SEPARATOR ',') AS invoice_date FROM tb_settlement_order s LEFT JOIN tb_settlement_invoice_line l ON s.ID = l.SETTLEMENT_ID AND l.IS_DELETED = 0 LEFT JOIN tb_contract_supplier c ON s.supplier_no = c.SUPPLIER_NO AND c.IS_DELETED = 0 LEFT JOIN tb_accept_apply a ON s.ACCEPT_APPLY_NO = a.APPLY_NO AND a.IS_DELETED = 0 WHERE s.IS_DELETED = 0
AND s.supplier_no = #{supplierNo}
AND s.SETTLEMENT_NO LIKE CONCAT('%', #{settlementNo}, '%')
AND s.STATUS = #{status}
AND s.ACCEPT_APPLY_NO LIKE CONCAT('%', #{acceptApplyNo}, '%')
AND a.BOM_PURCHASE_ORDER_NO LIKE CONCAT('%', #{bomOrderNo}, '%')
AND (a.PURCHASE_CONTRACT_NO LIKE CONCAT('%', #{contractNo}, '%') OR a.BOM_PURCHASE_CONTRACT_NO LIKE CONCAT('%', #{contractNo}, '%'))
GROUP BY s.ID ORDER BY s.CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM tb_settlement_order
WHERE IS_DELETED = 0

    AND supplier_no = #{supplierNo}

mapper.insert:
INSERT INTO tb_settlement_invoice_line (
    ID, SETTLEMENT_ID, INVOICE_NO, INVOICE_DATE, PROJECT_NAME, PART_NO,
    TAX_RATE, AMOUNT, TAX_AMOUNT, TOTAL_AMOUNT, ATTACHMENT_ID, ACCEPT_APPLY_NO, IS_DELETED,
    QUANTITY, UNIT
) VALUES (
    #{id}, #{settlementId}, #{invoiceNo}, #{invoiceDate}, #{projectName}, #{partNo},
    #{taxRate}, #{amount}, #{taxAmount}, #{totalAmount}, #{attachmentId}, #{acceptApplyNo}, 0,
    #{quantity}, #{unit}
)

mapper.select:
SELECT ID AS id, SETTLEMENT_NO AS settlementNo FROM tb_settlement_order WHERE IS_DELETED = 0 AND STATUS = 0 AND (
JSON_CONTAINS(ACCEPT_DETAIL_IDS, CAST(#{id} AS JSON))
)
